import{c,r as d,j as a}from"./index-70f42913.js";const u=c("Pause",[["rect",{width:"4",height:"16",x:"6",y:"4",key:"iffhe4"}],["rect",{width:"4",height:"16",x:"14",y:"4",key:"sjin7j"}]]),h=c("Play",[["polygon",{points:"5 3 19 12 5 21 5 3",key:"191637"}]]);function b({src:o,poster:i,alt:n,controls:e=!1,language:t="en",...m}){const[s,p]=d.useState(!1),g=t==="zh",l=s?g?"播放动画":"Play animation":g?"暂停动画":"Pause animation";return a.jsxs(a.Fragment,{children:[a.jsxs("picture",{className:"project-picture",children:[i&&a.jsx("source",{media:"(prefers-reduced-motion: reduce)",srcSet:i}),a.jsx("img",{src:s&&i?i:o,alt:n,...m})]}),i&&e&&a.jsxs("button",{className:"motion-toggle",onClick:()=>p(!s),"aria-label":l,children:[s?a.jsx(h,{size:13,"aria-hidden":"true"}):a.jsx(u,{size:13,"aria-hidden":"true"}),l]})]})}const v={en:[{id:1,category:"products",tags:["CHI 2026","UIST 2026 Demo","Generative AI","Spatial computing","XR interaction"],featured:!0,title:"Roomify",description:"Spatially grounded style transformation: turning real rooms into immersive virtual worlds through generative AI and cross-reality authoring.",year:"2025—2026",members:"Xueyang Wang, Qinxuan Cen, Weitao Bi, Yunxiang Ma, Xin Yi, Robert Xiao, Xinyi Fu, Hewu Li",sections:[{title:"A new world, in the room you know",content:`Roomify transforms an ordinary room into a themed virtual environment while retaining its layout, approximate furniture geometry, and recognizable functional roles. A sofa can become a spaceship seat; a refrigerator can become a pirate’s storage barrel. The real room becomes the structure for an imagined world.

The design challenge is to support immersion without losing awareness of nearby furniture. A formative study with eight participants informed four priorities: coherent and diverse styles, spatial alignment, functional consistency, and user control.

I co-designed the system and its XR interaction modules, and integrated an agent workflow connecting SLAM3R, SpatialLM, image generation, and 3D generation. The work was published at CHI 2026; a live demonstration was also accepted for UIST 2026.`,images:["/images/roomify-head.png"],imageCaptions:["From a room scan to an editable spatial scaffold and an immersive, themed environment."],zoomImages:!0,imageDimensions:[[1338,836]]},{title:"From a room scan to a generated world",content:`Scene understanding. A 30–60-second RGB video captured with a Quest 3 provides the input. SLAM3R reconstructs the room, and SpatialLM identifies its boundaries and furniture. Oriented 3D bounding boxes form a spatial scaffold that anchors later generation.

Style reasoning. An LLM agent translates text or image references into shared style, color, material, and atmosphere cues. It builds a mapping between physical objects and theme-appropriate counterparts, keeping high-level roles such as seating, storage, and support recognizable.

Content generation and registration. Reference views of each object guide GPT Image-1, followed by Tripo v2.5 image-to-3D generation. Wall and floor textures and an animated skybox are generated alongside the objects. The resulting assets are scaled, oriented, and placed against the scaffold; users inspect and refine their alignment before entering VR.`,images:["/images/roomify-pipeline.png"],imageCaptions:["The four-stage pipeline connects scene understanding, style reasoning, content generation, and spatial registration."],zoomImages:!0,imageDimensions:[[1529,638]]},{title:"An authoring workflow across MR and VR",content:`In mixed reality, creators inspect the scaffold over the physical room and correct object labels, position, orientation, and scale. Text, voice, and image references let them specify a theme. Generation progress remains visible, and objects flagged as collision risks require placement confirmation before the immersive preview.

Creators can reveal the real furniture through translucent generated objects, adjust individual assets, and regenerate selected elements without restarting the whole scene. Switching to VR brings the objects, room surfaces, animated surroundings, and ambient sound together. In Study 1, the complete transformation took an average of 19 minutes 46 seconds, with editing and generation overlapping.`,images:["/images/roomify-mr.png"],imageCaptions:["MR tools for spatial correction, multimodal style input, and selective regeneration, followed by VR preview."],zoomImages:!0,imageDimensions:[[1388,737]]},{title:"User studies",content:"We evaluated Roomify in two complementary studies: 18 VR users explored entertainment and navigation in a transformed living room, and eight design professionals assessed it as a tool for creative prototyping. The video below introduces the study conditions, tasks, and findings.",images:[],imageCaptions:[],zoomImages:!0,video:{src:"/videos/roomify-user-studies.mp4",poster:"/images/roomify-study-poster.jpg",width:1200,height:720,title:"Roomify user studies and evaluation",caption:"User-study walkthrough · 1 min 25 sec · Study 1: VR experience and navigation; Study 2: creative prototyping."}},{title:"Study 1 · Immersion and spatial awareness",content:`Eighteen participants experienced three counterbalanced conditions: passthrough, Roomify, and a fully virtual skybox with proximity-based boundary warnings and no virtual furniture. They watched a movie or played a game, then completed a treasure hunt that involved finding three gems and moving from a dining chair to a real sofa.

Roomify received the highest presence and experience ratings. Mean presence was 63% higher than passthrough and 26% higher than the fully virtual baseline, and 14 of 18 participants preferred Roomify. Spatial awareness fell between passthrough and fully virtual viewing—showing a trade-off rather than eliminating it.

The treasure-hunt completion time was numerically lowest with Roomify, but the difference was not statistically significant. Safety incidents were self-reported, and Roomify’s incident count lay between the two baselines. These findings apply to the specific conditions tested.`,images:["/images/roomify-presence-results.png","/images/roomify-usertest1.png"],imageCaptions:["Paper, Figure 9: presence, user experience, and spatial awareness. Baseline 1 = passthrough; Baseline 2 = fully virtual; Ours = Roomify.","Participant-created environments use different themes while retaining the room’s underlying spatial arrangement."],zoomImages:!0,table:{caption:"Study 1 · Mean ratings on 7-point scales · N = 18",columns:["Measure","Passthrough","Fully virtual","Roomify"],rows:[["Presence","3.65","4.72","5.94"],["User experience","4.92","5.27","6.27"],["Spatial awareness","6.20","4.41","5.10"]]},imageDimensions:[[1293,500],[1542,1006]]},{title:"Study 2 · A tool for creative prototyping",content:`Eight participants with backgrounds in architecture, visual arts, product design, and film compared Roomify with AI re-texturing of scanned geometry and text-to-3D generation. All methods used the same style prompts. Participants transformed both a physical living room and a ScanNet environment, freely choosing themes and comparing the results in VR.

Roomify received a System Usability Scale score of 84.38/100, and all eight participants preferred it. Designers highlighted early concept exploration, client communication, and storyboarding as promising uses. The results support its role as a prototyping tool; production assets still require manual refinement.`,images:["/images/roomify-method-comparison.jpg"],imageCaptions:["Paper, Figure 13: original rooms, AI re-texturing, Roomify, and text-to-3D results across maximalist, spacecraft, and kawaii themes."],zoomImages:!0,table:{caption:"Study 2 · Mean ratings on 7-point scales · N = 8",columns:["Measure","AI re-texturing","Text-to-3D","Roomify"],rows:[["Scene quality","3.41","4.50","5.95"],["Creativity support","3.73","5.09","6.08"]]},imageDimensions:[[1593,1313]]},{title:"What we learned, and what comes next",content:`Spatial grounding gives generative design a useful constraint: the physical room supplies an understandable structure, while generative models offer new visual possibilities. The authoring interface is essential to this balance, giving people ways to inspect and correct what the models produce.

Generation can still distort shape, proportions, and orientation. Moving or scaling an object cannot fix every mismatch, and the current system assumes static furniture rather than tracking people or pets. It preserves broad roles and geometry, not every physical action—a barrel can suggest storage without reproducing a refrigerator’s door mechanics or cooling.

The studies involved relatively young participants and individual experiences. More precise geometry, direct control over materials and shapes, live scene updates, and broader evaluations are priorities for further work. The fully virtual baseline’s lack of furniture and active boundary warnings also limit how broadly the presence comparison can be generalized.`,images:[],imageCaptions:[],zoomImages:!0}],links:[{label:"Paper · ACM",url:"https://doi.org/10.1145/3772318.3791803"},{label:"Preprint · arXiv",url:"https://doi.org/10.48550/arXiv.2603.04917"},{label:"Code · GitHub",url:"https://github.com/NiceStone-Hill/Virtual_Merge_Generation"}]},{id:2,category:"compdesign",tags:["Data Mining","NLP","Boardgame Design"],featured:!0,title:"Cognitive Tracks",description:"Turning campus movement data and visitors’ accounts into a board game and an AR guide.",year:"2023",members:"Individual project",sections:[{title:"Reading a campus through movement",content:"This individual project studies how people navigate Tsinghua’s campus. GPS traces and social-media posts identify places where visitors pause, the routes they take, and the associations they form. The findings inform a hexagonal board game and a mobile AR guide.",images:["/images/boardgame-flowchart.png"]},{title:"Fieldwork & analysis",content:`Under the supervision of Prof. Weixin Huang, I collected routes from 50 participants in August–September 2023. Python processing used Haversine distance and 60-second mean velocity to clean movement data. Low-speed samples (below 0.674 m/s) provided initial stopping candidates; density filtering and K-means identified 11 representative sites.

Around 200 Xiaohongshu posts contributed word-frequency and affective information. Combining these sources produced maps of visiting density, digital emotion, and physical stopping points.`,images:["/images/boardgame-experiment.png","/images/boardgame-clustering.png"]},{title:"From analysis to play",content:`The board and its components translate route patterns into choices players can make. The AR layer provides location-specific information.

Slower movement sometimes indicated congestion rather than interest, so velocity alone could not explain visitor preferences. Comparing interests in history, architecture, and nature helped distinguish different visiting sequences and dwell patterns.`,images:["/images/boardgame-design.png","/images/boardgame-result.png","/images/boardgame-effect.png"]}],links:[]},{id:3,category:"compdesign",tags:["EEG","Machine Learning","UX Design","Parametric Architecture"],featured:!0,title:"EEG-informed Exhibition Design",description:"Studying emotional responses to audiovisual stimuli and using the findings to inform modular exhibition spaces.",year:"2024—2025",members:"Yunxiang Ma, Yutong Wu",sections:[{title:"From perception to spatial design",content:"This group project connects EEG-based emotion recognition with modular exhibition design. It investigates how visual and auditory stimuli influence emotional response, then uses these findings to propose personalized routes through an exhibition. The work was selected for Tsinghua Architecture’s 2025 undergraduate exhibition.",images:["/images/imagine-experiment.png"]},{title:"Experimental study",content:`Three controlled studies, each with eight participants, compared visual, auditory, and audiovisual conditions. We recorded EEG using a 16-channel OpenBCI device at 256 Hz, with GSR and EMG as supplementary measures. Sessions lasted 15–20 minutes with 15-second stimulus epochs.

Preprocessing included band-pass and 50 Hz notch filtering, ICA artifact rejection, and baseline correction. We extracted power-spectrum and time-domain features, and compared SVM, KNN, and Random Forest classifiers using valence–arousal labels. Random Forest performed best among the tested classifiers.`,images:["/images/imagine-equipment.png","/images/imagine-data.png","/images/imagine-variables.png","/images/imagine-dataframe.png","/images/apparatus.png","/images/imagine-baseline.png","/images/imagine-ml.png"]},{title:"Modular proposal",content:`A 3 × 3 × 3 m prototype translates the study into spatial modules. A shape grammar defines 16 variants with different degrees of publicness, body posture, and circulation. Grasshopper scripts organize their assembly with horizontal and vertical circulation elements.

The proposal uses affect recognition to inform route recommendations. Personalized route recommendations remain a proposal for further evaluation.`,images:["/images/imagine-experience.png","/images/imagine-prototype.png","/images/imagine-shapegrammar.png","/images/imagine-grasshopper.png","/images/imagine-combination.png","/images/imagine-details.png","/images/imagine-final.png"]}],links:[]},{id:4,category:"dataviz",tags:["Urban Analysis","Computer Vision","ML","Clustering"],featured:!0,title:"Colors of Hong Kong",description:"Mapping street-level color patterns along Hong Kong’s Central–Mid-Levels Escalator.",year:"2024",members:"Yunxiang Ma, Jing Zhuang, Tino Zhu",sections:[{title:"A street-level study",content:"The study follows the Central–Mid-Levels Escalator, where commercial, residential, and heritage spaces meet. We examine how street-level color patterns relate to the corridor’s changing urban functions.",images:[]},{title:"Computer vision & clustering",content:"Street-view imagery was collected along the route and segmented with DeepLabV3 into elements such as buildings, trees, signs, pavement, and sky. We extracted color features, converted RGB values to HSV, reduced dimensionality with PCA, and grouped patterns with K-means.",images:["/images/hongkong-data.png","/images/hongkong-extraction.png","/images/hongkong-clustering.png"]},{title:"Color & urban function",content:"Within the sampled route, Central’s office and commercial areas tended toward cooler, less saturated palettes. Residential and mixed-use areas in Mid-Levels showed warmer, more saturated tones. Mapping these clusters provides a way to compare visual character with land use.",images:["/images/hongkong-result.png"]}],links:[]},{id:5,category:"products",tags:["UX Design","Mobile App","Product Design"],featured:!1,title:"Pet’s Tribe",description:"A mobile product concept bringing pet communities, adoption support, and everyday care into one place.",year:"2023",members:"Yunxiang Ma, Yuying Zhang, Xinning He, Rhone Ryan Huang Ern",sections:[{title:"Product question",content:"Pet owners and animal organizations often use separate services for community, adoption, and daily care. Pet’s Tribe explores how these activities could share a consistent mobile experience. Competitor research informed three areas: assistance, community, and a personal diary.",images:[]},{title:"Information architecture",content:"The assistance area supports adoption and care information. Community features organize posts and offline activities. The diary lets owners document daily life with privacy controls. Storyboards connect these features to different user needs and routines.",images:["/images/pet-structure.png","/images/pet-storyboard.png"]},{title:"Prototype & next evaluation",content:"The design progressed from sketches to a high-fidelity Figma prototype covering sign-in, user pathways, community, assistance, and diary screens. Planned usability evaluation would measure task completion, error recovery, and System Usability Scale scores; these are proposed measures, not reported results.",images:["/images/pet-prototype1.png","/images/pet-prototype2.png"]}],links:[]},{id:6,category:"xr",tags:["UX Design","VR","3D Scanning","Unity"],featured:!1,title:"Feeling Home in Memory",description:"Reconstructing a couple’s memories of home through interviews, 3D scanning, and VR.",year:"2024",members:"Individual project",sections:[{title:"Listening to a remembered home",content:"In July 2024, I interviewed a couple in Chongqing about their former and current homes. Their accounts of daily routines, shared spaces, and pets became the basis for an individual VR project about domestic memory.",images:[]},{title:"Interviews, drawings & capture",content:`The couple drew floor plans and traced changes in mood across a day and a year. Two scenes guided the reconstruction: family dinner at dusk in the former home, and reading at night in the current living room.

Mobile 3D scanning captured rooms and furniture. I assembled the scenes in Unity, using interview drawings to guide the selection of objects, light, and atmosphere.`,images:["/images/vr-sketch.png","/images/vr-workflow.png"]},{title:"The VR experience",content:"The final scenes combine scanned objects, generated skyboxes, and recorded soundscapes, including birds, traffic, and pets. Participants can move through the reconstructed rooms in a headset. The project treats personal accounts as design material, attending to the ordinary details that make a place feel like home.",images:["/images/vr-experience.png"]}],links:[]},{id:7,category:"products",tags:["NOVA Most InNOVAtive Prize","AI","Music Generation","Accessibility","Synesthesia","Web App"],featured:!0,title:"SyneSound",description:"A visual music-making interface that maps color, shape, and motion to musical structure.",year:"2025",members:"Yongyi Xiong, Yunxiang Ma",sections:[{title:"Composing through visual choices",content:"Developed by Yongyi Xiong and Yunxiang Ma, SyneSound explores visual composition for people without musical training and for Deaf and hard-of-hearing creators. Users arrange visual elements to specify musical ideas. The project received CMU NOVA’s Most InNOVAtive Prize.",images:["/images/SyneSound 1.png","/images/SyneSound 2.png"]},{title:"Visual-to-musical mapping",content:`Hue maps to modes; solid colors represent notes and blended colors represent chords. Position controls time and register, size sets duration, opacity controls dynamics, and rotation changes chord inversion. Motion encodes tempo, accent, and swing.

React, Konva, and Tone.js support the canvas and local interaction. Agentuity coordinates the generation workflow; OpenAI prepares prompts and MusicGen on Replicate generates audio.`,images:["/images/SyneSound 3.png","/images/SyneSound 4.png"]},{title:"Design intent & open questions",content:"Explicit visual mappings let collaborators discuss musical structure without relying entirely on notation or listening. The proposed next study pairs Deaf and hard-of-hearing composers with hearing audiences to examine whether the intended emotion is preserved in the generated music. Accessibility and emotional correspondence remain questions for evaluation.",images:["/images/SyneSound 5.png","/images/SyneSound 6.png"]}],links:[]},{id:8,category:"xr",tags:["WebXR","Browser AR","Three.js","Procedural Generation","Computer Vision","Serious Play"],featured:!0,title:"DomestiCade",description:"Turning photographs of everyday rooms into playable AR obstacle courses.",year:"2026",members:"Xinyi Li, Yongyi Xiong, Yunxiang Ma",sections:[{title:"A room as a game level",content:"DomestiCade is a browser-based AR platform game. A photograph of the surrounding room supplies objects and surfaces that the system translates into platforms, obstacles, collectibles, and goals. Players choose the scene; computational rules interpret its possibilities for play.",images:[]},{title:"Interpretation & implementation",content:"Computer vision provides semantic information for procedural level rules: a table edge can become a ledge, while a small object can become an obstacle. WebXR registers the resulting level in the physical room. The prototype uses Three.js, Cannon.js physics, serverless vision inference, and local 3D assets.",images:["/images/domesticade-pipeline.png"]},{title:"What the prototype explores",content:"The project examines how machine interpretation can contribute to a spatial game while keeping the player’s choice of place visible in the result. Its procedural rules balance recognizable room structure with navigable, playable geometry.",images:["/images/domesticade-scene.png"]}],links:[]},{id:9,category:"compdesign",tags:["Vision-Language Models","Spatial Reasoning","QLoRA","Qwen2.5-VL","InstaOrder","COCO"],featured:!0,title:"Spatial Depth Reasoning in VLMs",description:"Building a spatial-reasoning dataset and benchmark from public image resources, then fine-tuning and evaluating a 7B vision-language model end to end.",year:"2026",members:"Jingwu Wang, Yongyi Xiong, Yunxiang Ma",sections:[{title:"Building the dataset, not just tuning the model",content:`Our work focused on the complete experimental pipeline: reconstructing a task-specific dataset from public image resources, designing a benchmark, establishing baselines, fine-tuning a model, and analyzing its predictions. We built on COCO 2017 images and existing InstaOrder depth annotations; our contribution was turning those resources into controlled VLM instruction examples and an evaluation workflow.

The task is deliberately narrow: given an image and two localized objects, is Object A in front of or behind Object B? We extracted object pairs, instance masks, bounding boxes, and depth-order labels, preserved instance identity, and rendered images with boxes labeled A and B. This makes the intended pair explicit even when several objects share the same category.`,images:["/images/vlm-depth/dataset-example.png"],imageCaptions:["Final report, Figure 1 (p. 1): the original COCO image and two marked variants with the A/B identities swapped."],zoomImages:!0},{title:"A balanced, image-disjoint benchmark",content:`Each unordered object pair becomes two directional queries, (A, B) and (B, A), with reversed front/behind labels. Every split is therefore exactly balanced: always answering “front” cannot exceed 50% accuracy. We assign all pairs from one source image to a single split, preventing the same image from appearing in both training and evaluation.

The resulting dataset contains 26,046 training queries, 2,746 validation queries, and 2,952 test queries. These counts refer to directional examples, not unique images. We checked sample counts, label balance, image-disjointness, and rendered examples before running the experiments.`,images:[],table:{caption:"Dataset reconstructed from COCO 2017 images and InstaOrder annotations · final report, §2",columns:["Split","Directional queries","Front / behind"],rows:[["Training","26,046","50% / 50%"],["Validation","2,746","50% / 50%"],["Test","2,952","50% / 50%"]]}},{title:"Evaluating relationships and generated explanations",content:`We built a shared prompt, inference, and answer-parsing pipeline. Models generate a short rationale followed by a front/behind answer; the parser maps free-form responses to front, behind, or unknown. Every setting uses the same marked images, underlying pairs, labels, and splits.

Accuracy alone can hide directional guessing. Consistency Score measures whether reciprocal queries produce opposite labels; Pair Accuracy requires both directions to be correct. We also break accuracy down by target label, 2D overlap, and bounding-box IoU. A separate model-judge evaluation scores visual grounding, depth reasoning, and hallucination in the generated rationales. These scores are diagnostic signals, rather than proof that a model reasons correctly.`,images:["/images/vlm-depth/evaluation-metrics.png"],imageCaptions:["Final report, Table 2 (p. 3): evaluation metrics for individual decisions, reciprocal pairs, and generated rationales."],zoomImages:!0},{title:"From zero-shot baselines to QLoRA fine-tuning",content:`Our eight experimental settings compare 7B and 72B zero-shot Qwen2.5-VL baselines, three prompt-only 7B cue variants, and three QLoRA-tuned 7B variants. The spatial cues are bounding-box coordinates, a binary 2D-overlap flag, or both. Holding the data and marked-image inputs fixed lets us distinguish the effect of prompting from the effect of learning to use these cues.

We fine-tuned Qwen2.5-VL-7B with a frozen 4-bit NF4 backbone and trainable low-rank adapters: rank 64, scaling 128, dropout 0.05, bfloat16 computation, a learning rate of 1 × 10⁻⁴, and an effective batch size of 64. Training uses next-token cross-entropy over the generated target response, without a separate binary classification head.

The workflow extends through experiment scripts, distributed inference on Modal, output parsing, metric aggregation, and visualization. Main inference jobs used eight parallel containers with one NVIDIA B200 each. Our contribution is a controlled application and evaluation pipeline, rather than a new fine-tuning algorithm.`,images:["/images/vlm-depth/experiment-configurations.png"],imageCaptions:["Final report, Table 3 (p. 3): all eight configurations, with the same marked-image input throughout."],zoomImages:!0},{title:"The complete results",content:`The strongest configuration, 7B QLoRA with bounding boxes and overlap, achieved 92.65% accuracy, 96.82% consistency, and 91.06% pair accuracy. On this filtered test set, that is 42.14 percentage points above the 7B zero-shot baseline and 22.49 points above the 72B zero-shot reference. All three tuned variants exceeded 91% accuracy.

Prompt-only cues raised 7B accuracy to about 65–66%, but did not produce equally reliable reciprocal decisions. For example, overlap-only prompting reached 65.18% accuracy with 40.81% consistency. Fine-tuning delivered the larger improvement. The full report table below preserves all eight settings, subgroup results, and rationale-quality diagnostics.`,images:["/images/vlm-depth/results-summary.png"],imageCaptions:["Final report, Table 4 (p. 4): full experimental summary. “7B + bbox/ov” columns are QLoRA-tuned; “7B ZS + …” columns use prompting only. ZS = zero-shot; ov = overlap."],zoomImages:!0,table:{caption:"Key comparisons on the same 2,952-query test set",columns:["Model / setting","Accuracy","Consistency","Pair accuracy"],rows:[["7B zero-shot","50.51%","26.15%","21.61%"],["72B zero-shot","70.16%","67.01%","53.66%"],["7B QLoRA · bbox + overlap","92.65%","96.82%","91.06%"]]}},{title:"Reducing directional bias; testing occlusion",content:`The untuned 7B model was near chance overall, but its errors were strongly directional: 74.53% accuracy on front queries versus 26.49% on behind queries. With combined cues and QLoRA, those figures became 93.56% and 91.73%, respectively. The improvement therefore includes a much more balanced decision rule.

Occlusion remains harder. The strongest model reached 96.08% accuracy when the queried boxes did not overlap, but 75.80% when they did. Reporting these slices separately prevents the strong aggregate score from hiding the difficult cases.`,images:["/images/vlm-depth/direction-accuracy.png","/images/vlm-depth/overlap-accuracy.png"],imageCaptions:["Final report, Figure 4 (p. 5): accuracy by front/behind target label.","Final report, Figure 3 (p. 5): accuracy for overlapping and non-overlapping bounding boxes."],zoomImages:!0},{title:"Limits and next steps",content:`Performance also declines in the high-IoU bucket: the best model scored 77.78% when bounding-box IoU exceeded 0.3, compared with 93.08% at IoU = 0. Bounding boxes and a binary overlap flag are not enough to resolve every ambiguous scene.

The combined-cue model received a visual-grounding score of 4.80/5 and a 3.3% hallucination rate from the rationale judge, but the strongest evidence remains the decision and reciprocal-pair metrics. We have not established transfer to broader spatial benchmarks or verified that this specialized tuning preserves general VLM capabilities. Future work should test both, and explore richer visibility cues such as segmentation masks, visible-area ratios, relative scale, and depth-order priors.`,images:["/images/vlm-depth/iou-accuracy.png"],imageCaptions:["Final report, Figure 5 (p. 5): accuracy across bounding-box IoU buckets, showing the remaining difficulty of high-overlap cases."],zoomImages:!0}],links:[{label:"Code · GitHub",url:"https://github.com/yongyi2002/10623_project"}]},{id:10,category:"xr",tags:["Embodied interaction","Projection","Generative AI","Prototype"],featured:!0,title:"Peter Pan",year:"2026",members:"James Fu, Yunxiang Ma",coverFit:"cover",links:[],description:"A real-time embodied interaction prototype, using projected shadows to connect people, physical objects, and an animated character.",sections:[{title:"Shadow as an interface",content:`Peter Pan, Where Did the Shadow Go? explores shadow as a medium for embodied interaction. A projected, shadow-like character inhabits a wall or tabletop, and people influence it by moving objects, making gestures, and casting their own shadows into the scene. The physical surroundings become the interface.

Developed with James Fu for the Spring 2026 HyperSense course at CMU, the prototype connects camera-based perception with animated projection. Our focus was the immediate exchange between bodily action and a character’s visible response: how movement, pauses, and changes of direction make an interaction legible in a shared physical space.`,images:[],imageCaptions:[],imageDimensions:[],zoomImages:!0},{title:"Readings & brainstorming",content:"Several weeks of shared readings and discussion helped us connect embodied prompting, spatial interfaces, bodily awareness, explainable AI, and human–AI co-creation. The reading map brought these perspectives together and gave us a way to debate how people understand and influence an agent. For the prototype, we explored two ideas in particular: physical arrangements can guide behavior, and an abstract shadow can leave room for people to interpret a character’s intentions.",images:["/images/peter-pan-reading-map.jpg"],imageCaptions:["Reading map assembled by Evan from our shared readings and discussions on embodied and spatial AI interactions. Open the full-size image to explore the notes."],imageDimensions:[[2600,868]],zoomImages:!0,fullSizeImages:["/images/peter-pan-reading-map-full.jpg"]},{title:"Building a real-time prototype",content:`The project moved from an initial shadow concept in March to recognition experiments and an integrated prototype in April. A camera observes the interaction area; segmentation and a vision-language model identify the character object and surrounding elements. A calibrated 2D world plane connects their positions with the projection surface.

A reasoning layer interprets the scene and proposes actions, while the animation layer uses default and role-based behaviors such as walking, waiting, and jumping. The projector returns the character to the same physical surface, completing the loop. Moving a book, adding a paper platform, or placing a hand in the scene can change the conditions the character responds to.`,images:["/images/peter-pan-prototype-pipeline.png","/images/peter-pan-projection-setup.jpg"],imageCaptions:["Prototype pipeline from the final slides: physical perception, scene interpretation and planning, behavior generation, and projection.","Camera and projector arrangement from the final slides, aligning the physical object, recognition area, and projected character."],imageDimensions:[[2050,883],[1993,853]],zoomImages:!0},{title:"Showcase at CMU School of Design",content:`We presented the prototype at the CMU School of Design showcase, inviting visitors to interact directly with the projected character. People rearranged objects, built obstacles, tried to make the character jump, and used their own shadows to interrupt or guide it. These encounters made the prototype a shared, playful experience.

The demonstration also exposed practical design questions. Hand and arm detection was sometimes inconsistent, and visitors assigned different meanings to the same materials—for example, treating a sticky note as a path, ladder, or platform. Those responses pointed toward clearer feedback, more reliable calibration and perception, and a broader range of character behaviors.`,images:["/images/peter-pan-showcase-interaction.jpg"],imageCaptions:["A visitor encounters the projected shadow character during the CMU School of Design showcase."],imageDimensions:[[2048,1365]],zoomImages:!0}]},{id:11,category:"architecture",featured:!0,tags:["Architecture","Film translation","Museum design","Spatial narrative"],title:"Sinking Batavia: Museum of Accrete Culture",description:"An architectural translation of The Florida Project: three narrative worlds become a museum on Jakarta’s changing coast.",year:"2023",members:"Individual project · Yunxiang Ma",facts:[{label:"Location",value:"Jakarta, Indonesia"},{label:"Area",value:"2,920 m²"},{label:"Studio tutor",value:"Lu Fan (范路)"}],links:[{label:"Film reference · A24",url:"https://a24films.com/films/the-florida-project"},{label:"Jakarta · Land subsidence",url:"https://www.esdm.go.id/en/media-center/news-archives/head-of-geological-agency-groundwater-depletion-rate-can-be-slowed-down"}],sections:[{title:"Translating The Florida Project",content:`Sean Baker’s The Florida Project (2017) follows six-year-old Moonee and her mother Halley in a motel near a world of promised escape. Children’s play, adult precarity, and the everyday work of motel manager Bobby coexist in the same brightly colored setting. The film offers a starting point for thinking about how one place can hold different, sometimes conflicting realities.

I studied the film through frames, camera movement, and recurring scenes. Wide-angle views flatten the motel frontage into an apparently ordinary backdrop; two-shots reveal tension between people; following shots move with the children; close-ups bring emotional complexity into focus. These observations become architectural questions about framing, movement, visibility, and the relationship between an individual and a larger environment.`,images:["/images/batavia-florida-project.jpg","/images/batavia-film-analysis.jpg"],imageCaptions:["The Florida Project (2017), directed by Sean Baker. Official landscape promotional image published by A24.","Study of lens language: wide-angle views, two-shots, following shots, and close-ups, translated into spatial relationships."],imageDimensions:[[2400,823],[1833,1039]],zoomImages:!0,fullSizeImages:["/images/batavia-florida-project.jpg","/images/batavia-film-analysis.jpg"],imageCredits:[{label:"A24",url:"https://a24films.com/films/the-florida-project"}]},{title:"Three loops, three worlds",content:`Three narrative loops organize the reading. LOOP 1 traces Halley’s downward trajectory as her circumstances grow more constrained. LOOP 2 follows the mother–daughter relationship, connecting Moonee’s imaginative everyday world with Halley’s material pressures. LOOP 3 follows Bobby’s routine: a comparatively stable presence whose care and responsibilities repeatedly intersect with the residents’ lives.

From these intertwined loops, the project constructs UTOPIA, SELF, and REALITY. Rather than a strict Platonic opposition between Being and Becoming, this three-part structure leaves room for ambiguity: an imagined world, a situated self, and external conditions continually affect one another. The architectural translation works through layered spaces, shifting viewpoints, and connections between levels, allowing visitors to encounter these worlds as permeable relationships.`,images:["/images/batavia-narrative-loops.jpg","/images/batavia-three-worlds.jpg"],imageCaptions:["The three recurring narratives connect Halley, Moonee, and Bobby through contrasting trajectories and dependencies.","UTOPIA / SELF / REALITY: conceptual studies linking cinematic frames, spatial layers, and the position of the observer."],imageDimensions:[[1717,1742],[1656,830]],zoomImages:!0,fullSizeImages:["/images/batavia-narrative-loops.jpg","/images/batavia-three-worlds.jpg"]},{title:"Jakarta: a shore in transition",content:`The 2023 academic proposal locates the museum in Jakarta, where land subsidence and coastal exposure make the relationship between city and sea a pressing spatial question. Indonesia’s 2022 decision to legislate a new capital forms part of this changing urban context. The design imagines an abandoned coastal district toward 2050 as a speculative scenario, asking how architecture might remain entangled with a shifting shoreline over several decades.

Batavia, Jakarta’s former colonial name, points to another kind of accumulation. The research collage brings local, colonial, and incoming cultures into the same frame. The museum treats cultural identity as an ongoing process of coexistence and accretion. Its galleries and shared routes place these layers in relation to one another, while the site itself becomes a setting for reflecting on what a changing city carries forward.`,images:["/images/batavia-site.jpg","/images/batavia-cultural-layers.jpg"],imageCaptions:["Site study and master plan for the speculative coastal museum in Jakarta.","Cultural research collage: Jayakarta, Batavia, and Jakarta, with local, colonial, and incoming cultural layers."],imageDimensions:[[2200,719],[2200,824]],zoomImages:!0,fullSizeImages:["/images/batavia-site-full.jpg","/images/batavia-cultural-layers-full.jpg"]},{title:"Sky, ground, underground",content:`The building translates the three meaning worlds into a sectional composition of sky, ground, and underground. Most of the museum sits below grade, while elements above the surface establish a relationship with the landscape and open sky. The levels echo the film’s layered realities without fixing each visitor’s experience to a single interpretation.

Curved wall segments form the principal supports and shape column-free exhibition spaces. Two ring corridors at staggered heights connect galleries devoted to local, colonial, and incoming cultures, together with temporary exhibition and shared spaces. Two light shafts and one vertical circulation shaft link the layers from above to below. Movement, daylight, and framed views make the section legible: visitors descend through the building while retaining glimpses of the world overhead.`,images:["/images/batavia-plans.jpg","/images/batavia-section.jpg"],imageCaptions:["Plans across three levels: curved gallery walls, staggered ring corridors, and the shafts that connect them.","Section A–A: a low profile above ground and a layered sequence of galleries, circulation, and light below."],imageDimensions:[[2200,438],[2200,852]],zoomImages:!0,fullSizeImages:["/images/batavia-plans-full.jpg","/images/batavia-section-full.jpg"]},{title:"A cinematic route through light",content:`The final spatial sequence tests how cinematic ideas can be experienced through walking. Gallery passages alternate with openings and places to pause; changes in level reveal different relationships between the visitor, the curved walls, and the light shafts. Looking upward from the lower galleries offers a different reading of the same structure encountered from above.

The nine viewpoints pair an exploded axonometric with interior scenes, following the route from the upper spaces into the underground galleries. Daylit voids and darker exhibition rooms create changes in atmosphere along this route. The exterior rendering places the museum against an imagined coastal horizon, while the final interior rendering—used as the project cover—brings sky, circulation, and exhibition space into one frame.`,images:["/images/batavia-spatial-sequence.jpg","/images/batavia-exterior.jpg"],imageCaptions:["Space tour sequence: an exploded axonometric and nine viewpoints through light shafts, passages, stairs, and galleries.","Exterior study: the museum’s upper profile meets the imagined coastal landscape."],imageDimensions:[[2200,1554],[2062,1097]],zoomImages:!0,fullSizeImages:["/images/batavia-spatial-sequence-full.jpg","/images/batavia-exterior.jpg"]}]},{id:12,category:"architecture",featured:!0,year:"2021",coverFit:"cover",links:[],title:"The Other Perspective",description:"A community installation of collected plants, metal frames, and automatic irrigation, bringing people and nature together in an urban setting.",tags:["Installation","Design + build","Community participation","Coexistence"],members:"Tsinghua University, School of Architecture · 33 student builders",facts:[{label:"My role",value:"Co-director · one of two project leads"},{label:"Period",value:"August–October 2021"},{label:"Location",value:"CapitaMall, Taiyanggong, Beijing"},{label:"Recognition",value:"Best Popularity Award · four participating projects"}],sections:[{title:"Making coexistence spatial",content:`The Other Perspective is a public installation developed through design and construction for CapitaLand’s 2021 Charity & Life Festival. The concept of coexistence brings metal structures, community plants, and the people entering the pavilion into a shared setting. The relationship between city and nature becomes something encountered through looking, moving, and pausing.

We collected potted plants from the surrounding community that were struggling under poor care, left unused, or discarded. Suspended within a metal frame and connected to automatic irrigation, they became living components of a public space. The frame expresses an urban order while providing support and conditions for continued care.

I co-directed the project with another student, with responsibilities across concept and spatial design, material processing, construction, and publicity. A total of 33 students participated in the build. My role connected design intent, material and assembly decisions, fabrication arrangements, and on-site execution so the team could realize the installation together.`,images:["/images/perspective-concept.jpg"],imageCaptions:["Concept-to-build diagram: nature, self, and city are translated into plants, reflective panels, aluminum frames, and a public pavilion."],zoomImages:!0,imageDimensions:[[1388,319]],fullSizeImages:["/images/perspective-concept.jpg"]},{title:"From urban outlines to an inhabitable frame",content:`The site sits at CapitaMall in Beijing’s Taiyanggong district. We abstracted and inverted the outlines of nearby buildings to develop the frame’s geometric prototype. Rectangular elements at different heights intersect to create an open, layered environment within a compact footprint. Plans and sections at successive heights study the relationship between the frame, entrances, and places to pause.

The experience is designed around everyday actions: looking through frames at other people, approaching suspended plants, resting on a timber seat, or noticing one’s reflection. The illustrated scenarios are design intentions, bringing urban structure, natural growth, and the visitor’s own presence into the same field of view.`,images:["/images/perspective-site.jpg","/images/perspective-experience.jpg","/images/perspective-form.jpg"],imageCaptions:["Site and formal reference: neighboring buildings are abstracted and inverted to develop the metal frame.","Experience axonometric: open frames, suspended planting, reflective surfaces, and seating create opportunities to enter, look, and pause.","Form studies: frame compositions at different heights, with corresponding plans and sections."],zoomImages:!0,imageDimensions:[[1094,593],[1900,1647],[1097,1476]],fullSizeImages:["/images/perspective-site.jpg","/images/perspective-experience-full.jpg","/images/perspective-form.jpg"]},{title:"Detailing coexistence",content:`Aluminum profiles and connectors form the skeleton, integrating planting, lighting, irrigation, and reflective panels. Profile slots provide fixing points and house LED strips. Connected rectangular light loops outline the frame at night, placing its linear order alongside the less predictable forms of plants.

Automatic irrigation runs along the frame to water the hanging plants from above. Continued care is part of the coexistence concept, supported by the installation’s infrastructure. Reflective panels fit into the profile slots, overlapping views of the environment, plants, and visitors. The three-meter-square timber base is assembled to suit available board sizes; pine boards on the seats are processed into smaller pieces adapted to bodily contact and rest.`,images:["/images/perspective-assembly.jpg","/images/perspective-light-system.jpg","/images/perspective-led.jpg","/images/perspective-irrigation.jpg","/images/perspective-plants.jpg","/images/perspective-reflector.jpg","/images/perspective-floor.jpg","/images/perspective-seating.jpg","/images/perspective-connectors.jpg"],imageCaptions:["Exploded assembly: aluminum frame, planting, irrigation, light strips, reflective panels, seating, and the timber base.","01 Light system: connected vertical rectangles establish a continuous illuminated outline.","02 LED strips: inserted into profile slots to integrate lighting with the frame.","03 Automatic irrigation: waters suspended plants from top to bottom and controls the amount of water.","04 Hanging plants: collected community plants create a vertical layer within the metal frame.","05 Reflective-panel connection: panels fit into profile slots to frame and reflect the surroundings.","06 Timber base: a three-meter square assembled from five pinwheel-shaped board segments to suit material sizes.","07 Pine seating: smaller boards are processed to suit human scale and fixed to the seat structure.","08 Profile connectors: internal corner components connect the aluminum members."],zoomImages:!0,imageDimensions:[[1900,1334],[667,245],[667,239],[667,244],[667,248],[667,244],[667,252],[667,253],[667,268]],fullSizeImages:["/images/perspective-assembly-full.jpg","/images/perspective-light-system.jpg","/images/perspective-led.jpg","/images/perspective-irrigation.jpg","/images/perspective-plants.jpg","/images/perspective-reflector.jpg","/images/perspective-floor.jpg","/images/perspective-seating.jpg","/images/perspective-connectors.jpg"],imageLayout:"grid",imageSpans:[2]},{title:"A collective build by 33 students",content:`The construction diagram sets out four phases—plant collection, material processing, transportation, and on-site construction—with a build sequence marked from Day 1 to Day 30. Photographs document six concrete activities: collecting plants, cutting aluminum profiles, processing pine boards, assembling the frame, attaching light strips, and hanging plants.

As one of two co-directors, I contributed to the design and coordinated fabrication, construction, and publicity around a shared design intent. The participation of 33 students turned the drawn assembly into a sequence of cutting, connecting, installing, and arranging. The construction record makes that collective work visible.`,images:["/images/perspective-process.jpg","/images/perspective-collecting.jpg","/images/perspective-cutting.jpg","/images/perspective-woodwork.jpg","/images/perspective-assembling.jpg","/images/perspective-lighting.jpg","/images/perspective-hanging.jpg"],imageCaptions:["Build sequence: plant collection begins on Day 1, material processing on Day 7, transportation on Day 15, followed by on-site construction through Day 30.","01 · Collecting plants","02 · Cutting aluminum","03 · Processing pine","04 · On-site assembly","05 · Attaching light strips","06 · Hanging plants"],zoomImages:!0,imageDimensions:[[1900,295],[528,298],[528,294],[528,289],[528,304],[528,298],[528,305]],fullSizeImages:["/images/perspective-process-full.jpg","/images/perspective-collecting.jpg","/images/perspective-cutting.jpg","/images/perspective-woodwork.jpg","/images/perspective-assembling.jpg","/images/perspective-lighting.jpg","/images/perspective-hanging.jpg"],imageLayout:"grid",imageSpans:[3],imageColumns:3},{title:"Festival exhibition and recognition",content:`The completed installation was presented at CapitaLand’s 2021 Charity & Life Festival and received the Best Popularity Award among four participating projects. Its open frame, suspended plants, lighting, and timber places to pause brought the coexistence concept into a setting the public could approach and experience.

The project connected concept design, detailing, fabrication, teamwork, and public exhibition. For me, co-direction meant moving between the overall spatial intention and the practical decisions of making, helping a shared design take shape through the work of 33 student builders.`,images:["/images/perspective-cover.jpg"],imageCaptions:["Completed installation: light traces the metal frame while plants, reflective panels, and timber platforms share the space. This photograph also serves as the project cover."],zoomImages:!0,imageDimensions:[[2400,1921]],fullSizeImages:["/images/perspective-cover.jpg"]}]}],zh:[{id:1,category:"products",tags:["CHI 2026","UIST 2026 Demo","Generative AI","Spatial computing","XR interaction"],featured:!0,title:"Roomify",description:"以真实空间为基础的风格转换：通过生成式 AI 与跨现实创作，将真实房间转化为沉浸式虚拟世界。",year:"2025—2026",members:"Xueyang Wang, Qinxuan Cen, Weitao Bi, Yunxiang Ma, Xin Yi, Robert Xiao, Xinyi Fu, Hewu Li",sections:[{title:"在熟悉的房间里，进入另一个世界",content:`Roomify 将普通房间转化为主题化的虚拟环境，同时保留空间布局、家具的大致几何形态与可辨认的功能角色。沙发可以成为飞船座椅，冰箱可以被重新演绎为海盗船上的储物桶：真实房间为想象中的世界提供结构。

项目关注的问题是：如何提升沉浸感，同时让使用者仍能感知身边的家具？我们通过一项包含 8 名参与者的前期研究，确定了四个设计重点：风格的一致性与多样性、空间对齐、功能一致性，以及用户对生成结果的控制。

我参与了系统与 XR 交互模块的共同设计，并整合了连接 SLAM3R、SpatialLM、图像生成与三维生成的智能体工作流。研究发表于 CHI 2026，现场演示也获 UIST 2026 Demo 接收。`,images:["/images/roomify-head.png"],imageCaptions:["从房间扫描、可编辑的空间框架，到主题化的沉浸式虚拟环境。"],zoomImages:!0,imageDimensions:[[1338,836]]},{title:"从房间扫描到虚拟世界的生成流程",content:`场景理解。系统以 Quest 3 拍摄的 30–60 秒 RGB 房间视频作为输入，通过 SLAM3R 重建空间，再由 SpatialLM 识别房间边界与家具。带有方向信息的三维包围盒构成空间框架，为后续生成提供位置、朝向与尺度依据。

风格推理。语言模型智能体将文字或参考图像转化为统一的风格、色彩、材质和氛围描述，并建立真实物件与主题化物件之间的映射，使座椅、收纳、支撑等高层次功能仍可被理解。

内容生成与空间配准。系统选取每件物体的参考视角，用 GPT Image-1 生成风格化图像，再通过 Tripo v2.5 转化为三维模型；墙面、地面材质与动态天空盒同步生成。生成的资产依据空间框架调整尺度、朝向和位置，进入 VR 前由用户检查与修正对齐情况。`,images:["/images/roomify-pipeline.png"],imageCaptions:["四阶段流程：场景理解、风格推理、内容生成与空间配准。"],zoomImages:!0,imageDimensions:[[1529,638]]},{title:"在 MR 与 VR 之间创作和编辑",content:`在混合现实中，创作者可以对照真实房间检查空间框架，修正物件标签、位置、朝向和尺度，并通过文字、语音或图像描述主题。生成进度持续可见；被标记为存在碰撞风险的物件，需要在进入沉浸式预览前确认位置。

用户可以将生成物件半透明化，以查看背后的真实家具，也可以只调整或重新生成某个物件，无需重启整个场景。切换至 VR 后，物件、室内表面、动态环境与氛围声音共同构成完整体验。在研究一中，完成一次环境转换平均用时 19 分 46 秒，编辑与生成过程可以交叠进行。`,images:["/images/roomify-mr.png"],imageCaptions:["MR 中的空间校正、多模态风格输入与局部重新生成，以及 VR 中的沉浸式预览。"],zoomImages:!0,imageDimensions:[[1388,737]]},{title:"用户测试",content:"我们通过两项互补研究评估 Roomify：18 名 VR 用户在改造后的客厅中完成娱乐与导航任务，8 名设计专业参与者则评估其作为创意原型工具的表现。下面的视频介绍了两项研究的对照条件、任务与主要结果。",images:[],imageCaptions:[],zoomImages:!0,video:{src:"/videos/roomify-user-studies.mp4",poster:"/images/roomify-study-poster.jpg",width:1200,height:720,title:"Roomify 用户测试与评估介绍",caption:"用户测试介绍 · 1 分 25 秒 · 研究一：VR 体验与空间导航；研究二：创意原型设计。"}},{title:"研究一 · 沉浸感与空间感知",content:`18 名参与者以平衡顺序体验三种条件：视频透视、Roomify，以及不包含虚拟家具、带有接近边界提示的全虚拟天空盒环境。他们先观看影片或体验游戏，再使用虚拟手电筒寻找三颗宝石，并从餐椅移动到真实沙发，以评估空间导航与家具交互。

Roomify 获得了最高的临场感与体验评分。平均临场感评分比视频透视高 63%，比全虚拟基线高 26%；18 人中有 14 人更偏好 Roomify。其空间感知评分介于两种基线之间，说明系统在沉浸感与现实感知之间提供了一种折中。

寻宝任务中，Roomify 的平均完成时间最短，但差异未达到统计显著性。安全事件由参与者自行报告，Roomify 的平均事件次数同样介于两种基线之间。这些结果应在本研究的具体对照条件下理解。`,images:["/images/roomify-presence-results.png","/images/roomify-usertest1.png"],imageCaptions:["论文图 9：临场感、用户体验与空间感知。Baseline 1 为视频透视，Baseline 2 为全虚拟环境，Ours 为 Roomify。","参与者创作的多种主题环境：视觉风格发生变化，房间的基础空间关系得以保留。"],zoomImages:!0,table:{caption:"研究一 · 7 分量表的平均评分 · N = 18",columns:["指标","视频透视","全虚拟环境","Roomify"],rows:[["临场感","3.65","4.72","5.94"],["用户体验","4.92","5.27","6.27"],["空间感知","6.20","4.41","5.10"]]},imageDimensions:[[1293,500],[1542,1006]]},{title:"研究二 · 面向创意探索的原型工具",content:`8 名具有建筑、视觉艺术、产品设计和影视背景的参与者，将 Roomify 与两种生成方法进行比较：对扫描几何重新生成材质，以及直接通过文字生成三维模型。三种方法使用相同的风格提示词。参与者自由选择主题，分别改造真实客厅与 ScanNet 场景，并在 VR 中比较生成结果。

Roomify 的系统可用性量表（SUS）得分为 84.38/100，8 名参与者均将其选为最偏好的方法。设计者看好它在早期概念探索、客户沟通和分镜预演中的用途；面向正式生产的资产仍需要进一步的人工修整。`,images:["/images/roomify-method-comparison.jpg"],imageCaptions:["论文图 13：原始房间、AI 材质重绘、Roomify 与文字生成三维模型的对比，覆盖极繁主义、飞船与可爱风格。"],zoomImages:!0,table:{caption:"研究二 · 7 分量表的平均评分 · N = 8",columns:["指标","AI 材质重绘","文字生成三维","Roomify"],rows:[["场景质量","3.41","4.50","5.95"],["创意支持","3.73","5.09","6.08"]]},imageDimensions:[[1593,1313]]},{title:"设计启示与下一步",content:`真实空间为生成式设计提供了有意义的约束：房间本身给出可理解的结构，生成模型则带来新的视觉可能。创作界面是两者之间的重要连接，让使用者能够检查、修正和控制模型的输出。

生成结果仍可能出现形状、比例或朝向偏差，移动与缩放不能修复所有问题。当前系统假定家具保持静止，尚不能持续追踪人或宠物；它保留的是大致几何形态和功能角色，而非全部物理操作。例如，储物桶可以表达收纳功能，却不会复现冰箱的开门机制或制冷功能。

两项研究主要面向较年轻的参与者和单人体验。更准确的几何约束、对材质与形态的直接控制、动态场景更新，以及更广泛的用户评估，是后续的研究方向。全虚拟基线未包含家具且启用了边界提示，因此临场感结果也不宜直接推广到所有全虚拟环境。`,images:[],imageCaptions:[],zoomImages:!0}],links:[{label:"正式论文 · ACM",url:"https://doi.org/10.1145/3772318.3791803"},{label:"预印本 · arXiv",url:"https://doi.org/10.48550/arXiv.2603.04917"},{label:"代码 · GitHub",url:"https://github.com/NiceStone-Hill/Virtual_Merge_Generation"}]},{id:2,category:"compdesign",tags:["Data Mining","NLP","Boardgame Design"],featured:!0,title:"Cognitive Tracks",description:"将校园行动轨迹与访客叙述转化为桌游及 AR 导览。",year:"2023",members:"独立项目",sections:[{title:"从行动轨迹理解校园",content:"这项独立研究以清华校园为场地，结合 GPS 轨迹与社交媒体文本，分析访客的停留位置、路径选择及地点印象，并将结果转化为六边形桌游和移动 AR 导览。",images:["/images/boardgame-flowchart.png"]},{title:"调研与分析",content:`在黄蔚欣教授指导下，我于 2023 年 8—9 月采集了 50 位参与者的游览轨迹。使用 Python、Haversine 距离与 60 秒平均速度清洗数据，以低于 0.674 m/s 的低速样本筛选停留候选点，经密度过滤与 K-means 聚类提取 11 处代表性地点。

约 200 篇小红书帖子提供词频与情感信息。两类数据共同构成游览密度图、数字情感图与物理停留点地图。`,images:["/images/boardgame-experiment.png","/images/boardgame-clustering.png"]},{title:"从分析到游戏",content:`桌游棋盘与组件将路径模式转化为玩家可以选择的行动，AR 图层补充与地点相关的信息。

低速有时来自拥堵，而非吸引力，因此不能仅凭速度解释偏好。对历史、建筑和自然等不同兴趣群体进行比较，有助于区分游览顺序与停留模式。`,images:["/images/boardgame-design.png","/images/boardgame-result.png","/images/boardgame-effect.png"]}],links:[]},{id:3,category:"compdesign",tags:["EEG","Machine Learning","UX Design","Parametric Architecture"],featured:!0,title:"EEG 驱动的展览设计",description:"研究视听刺激下的情绪反应，并据此设计模块化展览空间。",year:"2024—2025",members:"Yunxiang Ma, Yutong Wu",sections:[{title:"从感知研究到空间设计",content:"项目将基于 EEG 的情绪识别与模块化展览设计结合，研究视觉和听觉刺激对情绪反应的影响，并据此提出个性化参观路径。作品入选清华大学建筑学院 2025 年本科毕业展。",images:["/images/imagine-experiment.png"]},{title:"实验研究",content:`三组受控实验各邀请 8 位参与者，对比视觉、听觉及视听融合条件。采用 16 通道 OpenBCI，以 256 Hz 采样，并辅以 GSR 与 EMG。每次实验持续 15—20 分钟，单个刺激时段为 15 秒。

预处理包括带通与 50 Hz 陷波、ICA 伪迹剔除和基线校正。提取功率谱及时间域特征，以效价—唤醒度标注比较 SVM、KNN 与随机森林，随机森林在测试模型中表现最佳。`,images:["/images/imagine-equipment.png","/images/imagine-data.png","/images/imagine-variables.png","/images/imagine-dataframe.png","/images/apparatus.png","/images/imagine-baseline.png","/images/imagine-ml.png"]},{title:"模块化空间方案",content:`方案以 3 × 3 × 3 m 空间原型转译实验结果，通过形态文法定义 16 种在公共性、身体姿态及流线方面不同的变体。Grasshopper 脚本组织模块与水平、垂直交通单元的拼装。

方案提出依据情绪识别推荐参观路径。个性化路径推荐仍属于有待进一步评估的设计方案。`,images:["/images/imagine-experience.png","/images/imagine-prototype.png","/images/imagine-shapegrammar.png","/images/imagine-grasshopper.png","/images/imagine-combination.png","/images/imagine-details.png","/images/imagine-final.png"]}],links:[]},{id:4,category:"dataviz",tags:["Urban Analysis","Computer Vision","ML","Clustering"],featured:!0,title:"香港的城市色彩",description:"沿香港中环至半山扶梯，识别并绘制街道色彩模式。",year:"2024",members:"Yunxiang Ma, Jing Zhuang, Tino Zhu",sections:[{title:"街道尺度的研究",content:"研究以中环至半山扶梯为线索，观察商业、住宅与历史空间相遇的街道，分析沿线色彩模式与城市功能变化的关系。",images:[]},{title:"计算机视觉与聚类",content:"沿线采集街景图像，用 DeepLabV3 识别建筑、树木、标识、铺地及天空等要素。提取色彩特征，将 RGB 转换为 HSV，经 PCA 降维后使用 K-means 对色彩模式聚类。",images:["/images/hongkong-data.png","/images/hongkong-extraction.png","/images/hongkong-clustering.png"]},{title:"色彩与城市功能",content:"在所采集的街段中，中环办公与商业片区较多呈现冷色、低饱和度的组合；半山住宅及混合功能区则更偏暖色、较高饱和度。将聚类结果映射回街道，可以对照视觉特征与土地使用。",images:["/images/hongkong-result.png"]}],links:[]},{id:5,category:"products",tags:["UX Design","Mobile App","Product Design"],featured:!1,title:"Pet’s Tribe",description:"整合宠物社区、领养协助与日常记录的移动产品概念。",year:"2023",members:"Yunxiang Ma, Yuying Zhang, Xinning He, Rhone Ryan Huang Ern",sections:[{title:"产品问题",content:"宠物主人与动物组织常需分别使用社区、领养及日常照护服务。Pet’s Tribe 研究如何将这些活动整合为一致的移动体验，竞品分析形成协助、社区与个人日记三个方向。",images:[]},{title:"信息架构",content:"协助模块组织领养流程与照护信息，社区模块承载帖子与线下活动，日记模块用于记录日常并设置可见范围。故事板将这些功能与不同用户的需求和习惯联系起来。",images:["/images/pet-structure.png","/images/pet-storyboard.png"]},{title:"原型与后续评估",content:"设计从草图发展为 Figma 高保真原型，涵盖登录、用户分流、社区、协助与日记。后续可用性评估计划关注任务完成率、错误恢复及 SUS 评分；这些是拟采用的指标，并非已完成的测试结果。",images:["/images/pet-prototype1.png","/images/pet-prototype2.png"]}],links:[]},{id:6,category:"xr",tags:["UX Design","VR","3D Scanning","Unity"],featured:!1,title:"Feeling Home in Memory",description:"通过访谈、三维扫描与 VR，重建一对夫妇关于家的记忆。",year:"2024",members:"独立项目",sections:[{title:"倾听关于家的记忆",content:"2024 年 7 月，我在重庆采访一对夫妇，了解他们对旧居与现居的记忆。他们讲述的日常习惯、共同使用的空间及宠物，构成了这项居住记忆 VR 项目的基础。",images:[]},{title:"访谈、绘图与扫描",content:`受访者绘制平面图，并记录一天及一年中的情绪变化。两个场景成为重建重点：旧居黄昏时的家庭晚餐，以及现居客厅里的夜间阅读。

通过移动三维扫描采集房间与家具，在 Unity 中重建场景，并依据访谈图纸选择物件、光线与环境氛围。`,images:["/images/vr-sketch.png","/images/vr-workflow.png"]},{title:"VR 体验",content:"最终场景结合扫描物件、生成式天空盒与鸟鸣、交通、宠物等实录声音。体验者可以佩戴头显在重建的房间中行走。项目将个人叙述作为设计材料，关注让人产生归属感的日常细节。",images:["/images/vr-experience.png"]}],links:[]},{id:7,category:"products",tags:["NOVA Most InNOVAtive Prize","AI","Music Generation","Accessibility","Synesthesia","Web App"],featured:!0,title:"SyneSound",description:"将颜色、形状与运动映射为音乐结构的可视化创作界面。",year:"2025",members:"Yongyi Xiong, Yunxiang Ma",sections:[{title:"以视觉选择创作音乐",content:"SyneSound 由 Yongyi Xiong 与 Yunxiang Ma 合作开发，面向缺少音乐训练的人群及聋人、重听创作者，探索通过编排视觉元素表达音乐想法。项目获得 CMU NOVA Most InNOVAtive Prize。",images:["/images/SyneSound 1.png","/images/SyneSound 2.png"]},{title:"视觉与音乐的映射",content:`色相对应调式，纯色代表单音，混色代表和弦。位置控制时间与音区，尺寸设置时值，透明度控制力度，旋转改变和弦转位，运动表达速度、重音与摇摆节奏。

React、Konva 与 Tone.js 支持画布和本地交互；Agentuity 协调生成流程，OpenAI 处理提示词，Replicate 上的 MusicGen 生成音频。`,images:["/images/SyneSound 3.png","/images/SyneSound 4.png"]},{title:"设计意图与待研究问题",content:"明确的视觉映射帮助协作者讨论音乐结构，减少对乐谱及聆听的依赖。后续拟邀请聋人、重听创作者与健听听众共同评估，检验生成音乐是否保留创作时的情绪意图。无障碍效果与情绪对应关系仍需进一步验证。",images:["/images/SyneSound 5.png","/images/SyneSound 6.png"]}],links:[]},{id:8,category:"xr",tags:["WebXR","Browser AR","Three.js","Procedural Generation","Computer Vision","Serious Play"],featured:!0,title:"DomestiCade",description:"将日常房间的照片转化为可游玩的 AR 障碍关卡。",year:"2026",members:"Xinyi Li, Yongyi Xiong, Yunxiang Ma",sections:[{title:"将房间理解为游戏关卡",content:"DomestiCade 是一款基于浏览器的 AR 平台游戏。用户拍摄周围房间，系统将其中的物体与表面转译为平台、障碍、收集物及目标。玩家选择场景，计算规则解析可用于游戏的空间结构。",images:[]},{title:"场景转译与实现",content:"计算机视觉为程序化关卡规则提供语义信息，例如将桌面边缘转为平台、小型物体转为障碍。WebXR 将生成关卡配准到真实房间。原型使用 Three.js、Cannon.js 物理引擎、无服务器视觉推理与本地三维素材。",images:["/images/domesticade-pipeline.png"]},{title:"原型探索的问题",content:"项目研究机器解释如何参与空间游戏设计，并在结果中保留玩家所选择场所的特征。程序化规则在可识别的房间结构与便于行动、游玩的几何关系之间进行协调。",images:["/images/domesticade-scene.png"]}],links:[]},{id:9,category:"compdesign",tags:["Vision-Language Models","Spatial Reasoning","QLoRA","Qwen2.5-VL","InstaOrder","COCO"],featured:!0,title:"视觉语言模型的空间深度推理",description:"基于公开图像资源重构空间推理数据集与 benchmark，完成 7B 视觉语言模型从基线评估到微调、实验分析的全流程。",year:"2026",members:"Jingwu Wang, Yongyi Xiong, Yunxiang Ma",sections:[{title:"从公开资源到自建数据集",content:`我们的工作重点是完整实验流程：基于公开图像资源重构任务数据集，设计 benchmark，建立基线，微调模型，并分析预测结果。我们使用 COCO 2017 图像和已有的 InstaOrder 深度标注；核心贡献是将这些资源整理为受控的 VLM 指令样本，并建立相应评测流程。

任务聚焦一个具体问题：给定图像与两个定位后的物体，A 位于 B 的前方还是后方？我们从原始标注中提取物体对、实例掩码、边界框与前后关系标签，保留实例身份，并在图像中绘制标记为 A、B 的边界框。即使同一类别出现多个物体，模型也能明确当前要判断的是哪一对。`,images:["/images/vlm-depth/dataset-example.png"],imageCaptions:["最终报告图 1，第 1 页：COCO 原始图像，以及交换 A/B 身份后的两种标记图像。"],zoomImages:!0},{title:"构建方向平衡、图像互斥的 benchmark",content:`每个无序物体对生成两条方向相反的查询：(A, B) 和 (B, A)，同时翻转 front/behind 标签。因此，每个数据划分的前后标签都严格各占 50%，始终回答“前方”的策略无法超过 50% 准确率。来自同一源图像的所有物体对只进入一个划分，避免训练与评估之间出现图像泄漏。

最终得到 26,046 条训练样本、2,746 条验证样本和 2,952 条测试样本。这里统计的是带方向的查询样本，而非独立图像数。实验前，我们检查样本数量、标签平衡、图像互斥性，并人工核查标记图像。`,images:[],table:{caption:"基于 COCO 2017 与 InstaOrder 重构的数据划分 · 最终报告第 2 节",columns:["数据划分","带方向的查询样本","前方 / 后方"],rows:[["训练集","26,046","50% / 50%"],["验证集","2,746","50% / 50%"],["测试集","2,952","50% / 50%"]]}},{title:"同时评估关系判断与生成式解释",content:`我们搭建统一的提示词、推理与答案解析流程。模型先生成简短理由，再给出前后关系结论；解析器将自由文本映射为 front、behind 或 unknown。所有实验使用相同的标记图像、物体对、标签和数据划分。

仅看准确率容易掩盖方向性猜测。一致性指标检查同一物体对的两次反向查询是否给出相反标签；成对准确率则要求两个方向都回答正确。我们还按前后标签、二维重叠情况和边界框 IoU 分组分析。另一个模型作为评审，对生成理由的视觉依据、深度推理与幻觉进行评分；这些评分用于诊断，不等同于对正确推理的证明。`,images:["/images/vlm-depth/evaluation-metrics.png"],imageCaptions:["最终报告表 2，第 3 页：覆盖单次判断、反向查询与生成理由的评测指标。"],zoomImages:!0},{title:"从零样本基线到 QLoRA 微调",content:`我们设计八组实验：7B 与 72B Qwen2.5-VL 零样本基线、三种仅在提示词中加入空间线索的 7B 变体，以及三种经过 QLoRA 微调的 7B 变体。空间线索分别为边界框坐标、二维重叠标记，以及二者组合。固定数据与标记图像输入，使实验能够区分“提供线索”和“训练模型使用线索”的作用。

微调使用冻结的 4-bit NF4 骨干网络和可训练低秩适配器：rank 为 64、scaling 为 128、dropout 为 0.05、bfloat16 计算、学习率为 1 × 10⁻⁴，有效 batch size 为 64。训练目标是生成式回答的 next-token 交叉熵，而非增加独立的二分类头。

全流程还包括实验脚本、Modal 分布式推理、输出解析、指标汇总与可视化。主要推理任务使用八个并行容器，每个容器配备一张 NVIDIA B200。项目贡献在于受控的任务应用和评测流程，而非提出新的微调算法。`,images:["/images/vlm-depth/experiment-configurations.png"],imageCaptions:["最终报告表 3，第 3 页：八组实验配置均使用相同的标记图像输入。"],zoomImages:!0},{title:"完整实验数据汇总",content:`最佳配置为“7B QLoRA + 边界框 + 重叠线索”，达到 92.65% 准确率、96.82% 一致性和 91.06% 成对准确率。在这个筛选后的测试集上，准确率比 7B 零样本基线高 42.14 个百分点，比 72B 零样本参照高 22.49 个百分点。三种微调配置的准确率均超过 91%。

仅增加提示线索能够将 7B 准确率提升至约 65–66%，但反向查询仍不够稳定。例如，仅增加重叠提示时，准确率为 65.18%，一致性却只有 40.81%。微调带来了更显著的提升。下方原始汇总表保留全部八种配置、分组结果和理由质量指标，便于完整比较。`,images:["/images/vlm-depth/results-summary.png"],imageCaptions:["最终报告表 4，第 4 页：完整实验汇总。“7B + bbox/ov”为 QLoRA 微调模型；“7B ZS + …”仅增加提示线索。ZS 表示零样本，ov 表示重叠线索。"],zoomImages:!0,table:{caption:"同一组 2,952 条测试查询上的关键对比",columns:["模型 / 配置","准确率","一致性","成对准确率"],rows:[["7B 零样本","50.51%","26.15%","21.61%"],["72B 零样本","70.16%","67.01%","53.66%"],["7B QLoRA · 边界框 + 重叠","92.65%","96.82%","91.06%"]]}},{title:"方向偏差与遮挡分析",content:`未微调的 7B 模型总体接近随机水平，但错误具有明显方向性：前方标签准确率为 74.53%，后方标签仅为 26.49%。经过组合线索微调后，两者分别达到 93.56% 和 91.73%。因此，改进不仅体现在总分上，也体现在更平衡的关系判断上。

遮挡仍然更难。最佳模型在边界框不重叠时达到 96.08%，重叠时降至 75.80%。单独呈现这些分组，可以避免较高的总体准确率掩盖困难样本。`,images:["/images/vlm-depth/direction-accuracy.png","/images/vlm-depth/overlap-accuracy.png"],imageCaptions:["最终报告图 4，第 5 页：按 front/behind 目标标签划分的准确率。","最终报告图 3，第 5 页：边界框重叠与不重叠条件下的准确率。"],zoomImages:!0},{title:"局限与下一步",content:`高 IoU 分组同样存在性能下降：最佳模型在边界框 IoU 大于 0.3 时的准确率为 77.78%，IoU 为 0 时为 93.08%。边界框和二元重叠标记仍不足以解决所有视觉歧义。

组合线索模型的评审结果为视觉依据 4.80/5、幻觉率 3.3%；但最有力的证据仍是判断准确率和反向查询指标。我们尚未验证结果能否迁移到更广泛的空间 benchmark，也未确认专项微调是否保留了模型原有的通用能力。后续工作应检验这两点，并探索分割掩码、可见面积比例、相对尺度和深度顺序先验等更丰富的线索。`,images:["/images/vlm-depth/iou-accuracy.png"],imageCaptions:["最终报告图 5，第 5 页：按边界框 IoU 分组的准确率，显示高重叠样本仍然较难。"],zoomImages:!0}],links:[{label:"Code · GitHub",url:"https://github.com/yongyi2002/10623_project"}]},{id:10,category:"xr",tags:["Embodied interaction","Projection","Generative AI","Prototype"],featured:!0,title:"Peter Pan",year:"2026",members:"James Fu, Yunxiang Ma",coverFit:"cover",links:[],description:"以投影中的影子为媒介，通过实时具身交互，连接人的身体动作、真实物件与动画角色。",sections:[{title:"让影子成为交互媒介",content:`Peter Pan, Where Did the Shadow Go? 探索以影子为媒介的具身交互。一个影子般的动画角色被投影到墙面或桌面上，人们通过移动物件、做出手势，或让自己的影子进入场景来影响它。周围的实体空间由此成为交互界面。

这个原型由我与 James Fu 在 CMU 2026 年春季 HyperSense 课程中共同完成，将摄像头感知与动画投影连接起来。我们关注身体动作与角色反馈之间的即时交流：角色的移动、停顿和转向，如何让同一物理空间中的互动变得可理解。`,images:[],imageCaptions:[],imageDimensions:[],zoomImages:!0},{title:"前期阅读与 brainstorm",content:"在数周的共同阅读与讨论中，我们梳理了具身提示、空间界面、身体感知、可解释 AI，以及人与 AI 共创等方向。Reading map 将这些观点并置，帮助我们讨论人如何理解和影响一个智能体。原型探索尤其关注两个想法：实体物件的摆放可以引导角色行为，而抽象的影子形态为使用者理解角色的意图留下空间。",images:["/images/peter-pan-reading-map.jpg"],imageCaptions:["由 Evan 整理的 reading map，汇集我们数周关于具身与空间 AI 交互的阅读、观点总结和讨论。可打开原图查看便签内容。"],imageDimensions:[[2600,868]],zoomImages:!0,fullSizeImages:["/images/peter-pan-reading-map-full.jpg"]},{title:"构建实时交互原型",content:`项目从 3 月的影子概念，逐步发展为识别实验，并在 4 月完成原型整合。摄像头观察交互区域，分割模块与视觉语言模型识别角色物件及周围元素，再通过校准后的二维世界平面，将物件位置对应到投影表面。

推理模块解释场景并规划动作，动画模块结合默认行为与角色化行为，呈现行走、等待、跳跃等反馈。投影仪将角色送回同一物理表面，形成持续的交互循环。移动一本书、加入纸片平台，或把手伸入场景，都可以改变角色所面对的空间条件。`,images:["/images/peter-pan-prototype-pipeline.png","/images/peter-pan-projection-setup.jpg"],imageCaptions:["来自最终 slides 的原型流程：物理感知、场景解释与动作规划、行为生成，以及投影反馈。","来自最终 slides 的装置布置：摄像头与投影仪连接真实物件、识别区域和投影角色。"],imageDimensions:[[2050,883],[1993,853]],zoomImages:!0},{title:"CMU School of Design showcase",content:`我们在 CMU School of Design 的 showcase 展示了原型，邀请观众直接与投影角色互动。人们会重新摆放物件、搭建障碍、尝试让角色跳跃，也会用自己的影子打断或引导它，让现场体验呈现出共同探索与游戏的氛围。

展示也暴露了具体的设计问题：手和手臂的识别有时不够稳定，同一种材料也可能被观众赋予不同含义，例如将便签理解为路径、梯子或平台。这些反馈为更清晰的交互提示、更可靠的校准与感知，以及更丰富的角色行为提供了下一轮调整方向。`,images:["/images/peter-pan-showcase-interaction.jpg"],imageCaptions:["CMU School of Design showcase 现场，观众与投影中的影子角色相遇。"],imageDimensions:[[2048,1365]],zoomImages:!0}]},{id:11,category:"architecture",featured:!0,tags:["建筑设计","电影转译","博物馆","空间叙事"],title:"巴达维亚之沉没：文化共生博物馆",description:"电影《佛罗里达乐园》影像空间转译：以三条叙事 LOOP 与三层意义世界，构想雅加达变化海岸上的博物馆。",year:"2023",members:"个人设计 · 马云翔",facts:[{label:"选址",value:"雅加达，印度尼西亚"},{label:"建筑面积",value:"2,920 m²"},{label:"指导教师",value:"范路"}],links:[{label:"电影资料 · A24",url:"https://a24films.com/films/the-florida-project"},{label:"雅加达 · 地面沉降",url:"https://www.esdm.go.id/en/media-center/news-archives/head-of-geological-agency-groundwater-depletion-rate-can-be-slowed-down"}],sections:[{title:"《佛罗里达乐园》的空间转译",content:`肖恩·贝克执导的《佛罗里达乐园》（2017）围绕六岁的 Moonee、母亲 Halley，以及汽车旅馆经理 Bobby 展开。孩子的游戏、成人的生存压力与维持旅馆运转的日常，共存于同一片色彩明亮的环境中。电影由此提供了一个空间命题：同一个地方，如何容纳不同甚至彼此冲突的现实？

我从画面构图、镜头运动与反复出现的场景入手，分析影片的空间语言。广角镜头将旅馆立面呈现为平直、客观的背景；双人镜头凸显人物关系中的冲突与紧张；跟随镜头进入孩子主观而生动的行动；特写则聚焦人物复杂的情绪。这些观察被转化为建筑中的取景、行进、可见性，以及个体与环境之间的关系。`,images:["/images/batavia-florida-project.jpg","/images/batavia-film-analysis.jpg"],imageCaptions:["《佛罗里达乐园》（2017），肖恩·贝克导演。横版宣传图来自 A24 官方电影页面。","镜头语言分析：广角、双人镜头、跟随镜头与特写，及其对应的空间关系研究。"],imageDimensions:[[2400,823],[1833,1039]],zoomImages:!0,fullSizeImages:["/images/batavia-florida-project.jpg","/images/batavia-film-analysis.jpg"],imageCredits:[{label:"A24",url:"https://a24films.com/films/the-florida-project"}]},{title:"三条 LOOP 与三层意义世界",content:`叙事分析提取了三条相互缠绕的 LOOP。LOOP 1 描绘 Halley 的生活逐渐下沉，外部处境持续收紧；LOOP 2 围绕母女之间的依赖，将 Moonee 的日常想象与 Halley 的现实压力连接起来；LOOP 3 追踪旅馆经理 Bobby 的日常，他以相对稳定的自身位置，在照护、管理与居民生活之间不断往返。

在此基础上，项目建构了 UTOPIA、SELF、REALITY 三层意义世界。区别于柏拉图式 Being / Becoming 的二元对立，三段式结构保留了更模糊的中间地带：想象中的世界、身处其中的自我与外部现实不断互相影响。建筑通过空间叠合、视点变化与层间连接，让三层世界成为可以穿越和重新理解的关系，而非互不相通的分类。`,images:["/images/batavia-narrative-loops.jpg","/images/batavia-three-worlds.jpg"],imageCaptions:["电影叙事拼贴：Halley、Moonee 与 Bobby 的三条 LOOP，以不同轨迹与人物依赖组织空间概念。","UTOPIA / SELF / REALITY：将电影画面、空间层次与观察者的位置并置，提取三重意义世界。"],imageDimensions:[[1717,1742],[1656,830]],zoomImages:!0,fullSizeImages:["/images/batavia-narrative-loops.jpg","/images/batavia-three-worlds.jpg"]},{title:"雅加达：变化中的海岸",content:`这份 2023 年的课程设计选址于印度尼西亚雅加达。持续的地面沉降与沿海风险，使城市与海洋的关系成为重要的空间议题；2022 年印度尼西亚通过新首都相关法律，也构成城市转变的背景。项目以面向 2050 年的废城海岸作为构想情景，探讨一座建筑如何在未来数十年中，与变化的地面和海平面持续纠缠。

“巴达维亚”是雅加达历史上的殖民时期名称，也指向文化的层层积累。前期拼贴将本土文化、殖民文化与外来文化放入同一时间与空间框架。博物馆以文化共生为主题，通过展厅与共享路径，让不同文化层次彼此相遇；不断变化的城市本身，也成为思考记忆、延续与未来的场所。`,images:["/images/batavia-site.jpg","/images/batavia-cultural-layers.jpg"],imageCaptions:["雅加达海岸场地研究与博物馆总平面，呈现构想情景中的城市、岸线与建筑关系。","文化研究拼贴：从 Jayakarta、Batavia 到 Jakarta，梳理本土、殖民与外来文化的交叠。"],imageDimensions:[[2200,719],[2200,824]],zoomImages:!0,fullSizeImages:["/images/batavia-site-full.jpg","/images/batavia-cultural-layers-full.jpg"]},{title:"天空、地面与地下",content:`建筑采用天空—地面—地下的三段式构图，将三层意义世界转译为剖面中的空间关系。主体展览空间沉入地下，地表以上的构筑则与周围地景和天空建立联系。三层空间呼应电影中的多重现实，同时为访客保留不同的观看与理解方式。

多段曲面片墙承担主要支撑，围合出无柱的展览空间；两层高低错落的环廊串联本土、殖民与外来文化展厅，以及临时展览和共享空间。两个采光桶与一个纵向交通桶自上而下贯穿建筑，将天空、地面与地下连接起来。行进路径、自然光与被框取的视野共同呈现剖面层次，使访客在向下深入建筑时，仍能看到上方世界的片段。`,images:["/images/batavia-plans.jpg","/images/batavia-section.jpg"],imageCaptions:["三层平面：曲面展墙、错层环廊，以及连接各层的采光与交通空间。","A–A 剖面：地表以上的低矮轮廓，与地下展厅、环廊和采光空间的层叠关系。"],imageDimensions:[[2200,438],[2200,852]],zoomImages:!0,fullSizeImages:["/images/batavia-plans-full.jpg","/images/batavia-section-full.jpg"]},{title:"以光组织空间游览序列",content:`最终的空间游览序列，检验电影中的观看方式如何转化为身体行进的体验。展厅通道与开敞空间、停留节点交替出现；高度变化让访客重新理解自身与片墙、采光桶之间的关系。从地下仰望时，同一结构又呈现出不同于地面俯视的空间感受。

九个视点将分解轴测与室内场景对应，沿着上部空间逐步进入地下展厅。明亮的采光空腔与较暗的展览空间，形成连续行进中的氛围变化。室外渲染将建筑放入想象中的海岸地景；作为项目封面的最后一张室内渲染，则把天空、纵向交通与展览空间收束于同一画面。`,images:["/images/batavia-spatial-sequence.jpg","/images/batavia-exterior.jpg"],imageCaptions:["空间游览序列：分解轴测与九个视点，串联采光桶、通道、楼梯与不同层次的展厅。","室外空间研究：博物馆的地表轮廓与构想中的海岸地景相接。"],imageDimensions:[[2200,1554],[2062,1097]],zoomImages:!0,fullSizeImages:["/images/batavia-spatial-sequence-full.jpg","/images/batavia-exterior.jpg"]}]},{id:12,category:"architecture",featured:!0,year:"2021",coverFit:"cover",links:[],title:"另一种视角：共生装置",description:"以社区盆栽、金属框架与自动灌溉构建公共装置，在城市日常中呈现人与自然的共生。",tags:["装置设计","设计与搭建","社区参与","共生"],members:"清华大学建筑学院 · 33 位同学参与搭建",facts:[{label:"我的角色",value:"联合统筹者（两人共同统筹）"},{label:"时间",value:"2021 年 8 月—10 月"},{label:"地点",value:"北京太阳宫 · 凯德 Mall"},{label:"获奖",value:"最佳人气奖 · 四个参展项目"}],sections:[{title:"让共生成为可以进入的空间",content:`The Other Perspective（另一种视角）是一项从设计走向现场搭建的公共装置，于 2021 年参加凯德 Mall 公益生活节。项目以“共生”为概念，将城市中的金属结构、社区中的植物，以及进入装置的人放入同一空间，让人与自然的关系通过停留、观看和身体体验被感知。

我们收集社区内因养护不当而生长不佳、被闲置或丢弃的盆栽，将它们悬挂于金属框架中，并接入自动灌溉。植物由分散在家庭中的盆栽，成为共同构成公共空间的生命材料；框架既承载城市的秩序，也为植物继续生长提供支撑与养护条件。

我与另一位同学联合统筹项目，工作覆盖概念与空间设计、材料加工、施工搭建及宣传。共有 33 位同学参与建造。我的角色是将设计意图、材料和构造选择、加工安排与现场实施连接起来，推动团队共同完成装置。`,images:["/images/perspective-concept.jpg"],imageCaptions:["概念与建造流程：自然、自我与城市的关系，落实为植物、反射板、铝型材框架及公共装置。"],zoomImages:!0,imageDimensions:[[1388,319]],fullSizeImages:["/images/perspective-concept.jpg"]},{title:"从城市轮廓到可停留的框架",content:`场地位于北京太阳宫的凯德 Mall。我们观察周边建筑，将其轮廓抽象、翻转，再转化为装置的几何原型。不同高度的矩形框架相互穿插，在有限的场地中形成开放而有层次的空间。形态推演通过不同高度的平面与剖面，检验框架、入口和停留空间之间的关系。

体验围绕简单的日常动作展开：穿过框架观看别人、靠近悬挂的植物、在木质座椅上休息，或在反射板中看到自己的身影。图中的体验场景是设计设想，旨在让城市结构、自然生长与人的存在同时进入视野。`,images:["/images/perspective-site.jpg","/images/perspective-experience.jpg","/images/perspective-form.jpg"],imageCaptions:["场地与形态来源：抽象并翻转周边建筑，形成金属框架的原型。","体验轴测：开放框架、悬挂植物、反射面与座椅共同组织可进入、可观看、可停留的空间。","形态推演：不同高度的框架组合，以及对应的平面和剖面研究。"],zoomImages:!0,imageDimensions:[[1094,593],[1900,1647],[1097,1476]],fullSizeImages:["/images/perspective-site.jpg","/images/perspective-experience-full.jpg","/images/perspective-form.jpg"]},{title:"将共生落实为构造",content:`装置以铝型材和连接件组成骨架，将植物、灯带、灌溉和反射板整合在同一套构造中。型材的槽口既用于固定部件，也容纳 LED 灯带；多个矩形光带在夜间描绘框架，让金属的线性秩序与植物的自然形态并置。

自动灌溉系统沿框架布置，从上向下为悬挂植物供水。植物需要持续照料，因此“共生”既是可见的空间形态，也落实为养护的支持。反射板嵌入型材槽口，使周围环境、植物与观众的身影交织。地面平台为 3 米见方，依据原材料尺寸拼合；座椅表面的松木板经过加工，回应身体接触和停留的尺度。`,images:["/images/perspective-assembly.jpg","/images/perspective-light-system.jpg","/images/perspective-led.jpg","/images/perspective-irrigation.jpg","/images/perspective-plants.jpg","/images/perspective-reflector.jpg","/images/perspective-floor.jpg","/images/perspective-seating.jpg","/images/perspective-connectors.jpg"],imageCaptions:["分解轴测：铝型材骨架、悬挂植物、自动灌溉、灯带、反射板、座椅及木地台的装配关系。","01 光带系统：多个竖向矩形连接，形成整体的光线轮廓。","02 LED 灯带：嵌入铝型材槽口，使照明与框架结合。","03 自动灌溉：从上向下为悬挂植物供水，并自动控制水量。","04 悬挂植物：将社区收集的盆栽纳入金属框架，形成垂直的植物层。","05 反射板连接：板材嵌入型材槽口，形成取景与反射效果。","06 木地台：3 米见方，按照材料尺寸以五块风车状板面拼合。","07 松木座面：加工为适应人体尺度的小板，再固定于座椅骨架。","08 型材连接件：通过内置角部件连接铝型材。"],zoomImages:!0,imageDimensions:[[1900,1334],[667,245],[667,239],[667,244],[667,248],[667,244],[667,252],[667,253],[667,268]],fullSizeImages:["/images/perspective-assembly-full.jpg","/images/perspective-light-system.jpg","/images/perspective-led.jpg","/images/perspective-irrigation.jpg","/images/perspective-plants.jpg","/images/perspective-reflector.jpg","/images/perspective-floor.jpg","/images/perspective-seating.jpg","/images/perspective-connectors.jpg"],imageLayout:"grid",imageSpans:[2]},{title:"33 位同学共同完成的搭建",content:`施工图将过程分为植物收集、材料加工、运输与现场搭建四个阶段，并标示从第 1 天到第 30 天的建造顺序。实际制作记录进一步展开了六个环节：收集植物、切割铝型材、加工松木板、组装框架、安装灯带，以及悬挂植物。

作为两位联合统筹者之一，我参与设计，并协调加工、建造与宣传，让各环节围绕同一设计目标衔接。33 位同学的共同参与，使装置从图纸上的装配关系走向真实的切割、连接、安装和布置；施工照片保留了这一集体建造过程。`,images:["/images/perspective-process.jpg","/images/perspective-collecting.jpg","/images/perspective-cutting.jpg","/images/perspective-woodwork.jpg","/images/perspective-assembling.jpg","/images/perspective-lighting.jpg","/images/perspective-hanging.jpg"],imageCaptions:["建造流程图：第 1 天开始收集植物，第 7 天材料加工，第 15 天运输，随后进入现场搭建，至第 30 天完成图示流程。","01 · 收集植物","02 · 切割铝型材","03 · 加工松木板","04 · 现场组装","05 · 安装灯带","06 · 悬挂植物"],zoomImages:!0,imageDimensions:[[1900,295],[528,298],[528,294],[528,289],[528,304],[528,298],[528,305]],fullSizeImages:["/images/perspective-process-full.jpg","/images/perspective-collecting.jpg","/images/perspective-cutting.jpg","/images/perspective-woodwork.jpg","/images/perspective-assembling.jpg","/images/perspective-lighting.jpg","/images/perspective-hanging.jpg"],imageLayout:"grid",imageSpans:[3],imageColumns:3},{title:"公益生活节展出与最佳人气奖",content:`完成后的装置在 2021 年凯德 Mall 公益生活节展出，并在四个参展项目中获得最佳人气奖。开放的框架、悬挂植物、灯光与木质停留空间，将“共生”转化为公众能够走近并体验的环境。

这次实践把概念设计、构造细节、加工制作、团队协作与公共展示连接起来。对我而言，联合统筹意味着持续在整体空间与具体制作之间往返，让共同的设计意图通过 33 位同学的协作落地。`,images:["/images/perspective-cover.jpg"],imageCaptions:["最终实景：灯带描绘金属框架，植物、反射面与木质平台共同构成装置。此图也用作项目封面。"],zoomImages:!0,imageDimensions:[[2400,1921]],fullSizeImages:["/images/perspective-cover.jpg"]}]}]},r=[1,10,9,8,7,3,6,4,11,2,5,12],y={1:"/images/roomify-demo.gif",2:"/images/boardgame-head.png",3:"/images/imagine-head.png",4:"/images/hongkong-head.png",5:"/images/pet-head.png",6:"/images/vr-head.png",7:"/images/SyneSound 1.png",8:"/images/domesticade-heroimage.png",9:"/images/VLMFT-method.png",10:"/images/peter-pan-showcase-cover.jpg",11:"/images/batavia-cover.jpg",12:"/images/perspective-cover.jpg"},w={1:{en:"Generative environments, grounded in real space.",zh:"以真实空间为基础的生成式虚拟环境。",recognition:"CHI 2026 · UIST 2026 Demo",image:"/images/roomify-demo-card.gif",poster:"/images/roomify-demo-poster.jpg"},9:{en:"A custom depth benchmark, from public data to model tuning.",zh:"从公开数据到自建深度评测基准与模型微调。",image:"/images/VLMFT-img.png",fit:"contain"},10:{en:"A projected shadow, a physical space, and a playful exchange.",zh:"以影子为媒介，在真实空间中展开具身交互。",recognition:"CMU School of Design Showcase"},11:{title:{en:"Sinking Batavia",zh:"巴达维亚之沉没"},en:"Three cinematic worlds, translated into a coastal museum.",zh:"将电影中的三层世界转译为海岸上的文化共生博物馆。"},12:{title:{en:"The Other Perspective",zh:"另一种视角"},en:"A community pavilion for people, plants, and the city.",zh:"以共同建造的公共装置，呈现人、植物与城市的共生。",recognition:"Best Popularity Award"},7:{en:"Making music through color, shape, and motion.",zh:"用色彩、形状与动作创作音乐。",image:"/images/SyneSound 6.png",recognition:"NOVA Most InNOVAtive Prize"},8:{en:"Everyday rooms become playable AR worlds.",zh:"将日常房间变成可玩的 AR 世界。"},6:{en:"Reconstructing memories of home in virtual reality.",zh:"在虚拟现实中重建关于家的记忆。"},3:{en:"From emotional responses to exhibition spaces.",zh:"从情绪感知到展览空间设计。"},2:{en:"Campus movement translated into a game and AR guide.",zh:"将校园行为数据转化为桌游与 AR 导览。"},4:{en:"Reading a city through its street-level colors.",zh:"通过街道色彩，观察与理解城市。"},5:{en:"A place for pet communities, adoption, and care.",zh:"连接宠物社群、领养与日常照护。"}},j=[{id:"all",en:"All work",zh:"全部",ids:null},{id:"products",en:"Products",zh:"产品",ids:[1,5,7]},{id:"compdesign",en:"Computational design",zh:"计算设计",ids:[2,3,9]},{id:"architecture",en:"Architecture",zh:"建筑",ids:[11,12]},{id:"dataviz",en:"Data & cities",zh:"数据与城市",ids:[4]},{id:"xr",en:"Spatial experiences",zh:"空间体验",ids:[1,6,8,10,12]}];function x(o){const i=e=>Math.max(...(String(e.year||"").match(/\d{4}/g)||["0"]).map(Number)),n=e=>r.includes(e)?r.indexOf(e):r.length;return[...o].sort((e,t)=>e.id===1||t.id===1?+(t.id===1)-+(e.id===1):i(t)-i(e)||n(e.id)-n(t.id))}export{b as P,w as a,y as b,v as c,x as o,j as p};
